export async function seedExcelDataToLocalAndCloud(): Promise<{ success: boolean; countClasses: number; countStudents: number }> {
  try {
    const { addClass, addStudent } = await import('./dbAttendance');
    const { syncService } = await import('./sync');
    
    // Set active school ID in localStorage
    if (typeof window !== 'undefined') {
      localStorage.setItem('active_school_id', SMAN19_SCHOOL_ID);
    }
    
    console.log('[Seed] Seeding 15 classes to IndexedDB...');
    for (const cls of SEED_CLASSES) {
      await addClass(cls as any);
    }

    console.log('[Seed] Seeding 669 students to IndexedDB...');
    for (const stud of SEED_STUDENTS) {
      await addStudent(stud as any);
    }

    console.log('[Seed] Pushing seeded data to Supabase Cloud...');
    if (syncService.isConfigured()) {
      const result = await syncService.pushToCloud();
      console.log('[Seed] Sync Push Result:', result);
    }

    return {
      success: true,
      countClasses: SEED_CLASSES.length,
      countStudents: SEED_STUDENTS.length
    };
  } catch (error) {
    console.error('[Seed] Failed to seed data:', error);
    return { success: false, countClasses: 0, countStudents: 0 };
  }
}
